package io.hyperswitch.authentication

import android.app.Activity
import io.hyperswitch.click_to_pay.BuildConfig
import io.hyperswitch.click_to_pay.ClickToPaySession
import io.hyperswitch.click_to_pay.models.ClickToPayErrorType
import io.hyperswitch.click_to_pay.models.ClickToPayException
import io.hyperswitch.logs.EventName
import io.hyperswitch.logs.HSLog
import io.hyperswitch.logs.HyperLogManager
import io.hyperswitch.logs.LogCategory
import io.hyperswitch.logs.LogType
import io.hyperswitch.logs.LogUtils.getOrCreateUniqueKey

/**
 * Default implementation of AuthenticationSessionLauncher.
 *
 * This class manages the lifecycle of authentication and Click to Pay sessions,
 * handling initialization, credential storage, and session creation.
 *
 * @property clickToPaySession The underlying Click to Pay session instance
 * @property clientSecret Stored client secret from payment intent
 * @property profileId Stored merchant profile identifier
 * @property authenticationId Stored authentication session identifier
 * @property merchantId Stored merchant identifier
 */
class DefaultAuthenticationSessionLauncher(
    activity: Activity,
    publishableKey: String,
    customBackendUrl: String? = null,
    customLogUrl: String? = null,
): AuthenticationSessionLauncher {

    private val clickToPaySession: ClickToPaySession = ClickToPaySession(
        activity,
        publishableKey,
        customBackendUrl,
        customLogUrl,
    )
    private var clientSecret: String? = null
    private var profileId: String? = null
    private var authenticationId: String? = null
    private var merchantId: String? = null
    private val sessionId = getOrCreateUniqueKey(activity, "click_to_pay")

    /**
     * Initializes the Click to Pay SDK.
     *
     * Loads required resources and prepares the SDK for use.
     * Must be called before any Click to Pay operations.
     *
     * @throws Exception if SDK initialization fails
     */
    @Throws(Exception::class)
    override suspend fun initialize() {
        clickToPaySession.initialise()
    }

    internal fun logger(
        type: LogType,
        eventName: EventName,
        value: String,
        category: LogCategory = LogCategory.USER_EVENT,
        authenticationId: String? = this.authenticationId
    ) {
        val log = HSLog.LogBuilder()
            .logType(type)
            .category(category)
            .eventName(eventName)
            .value(value)
            .version(BuildConfig.VERSION_NAME)
            .authenticationId(authenticationId.orEmpty())
            .sessionId(sessionId)
        HyperLogManager.addLog(log.build())
    }



    /**
     * Stores authentication credentials for subsequent operations.
     *
     * These credentials are used when initializing Click to Pay sessions
     * without explicitly providing them each time.
     *
     * @param clientSecret The client secret from the payment intent
     * @param profileId The merchant profile identifier
     * @param authenticationId The authentication session identifier
     * @param merchantId The merchant identifier
     */
    @Throws(Exception::class)
    override suspend fun initAuthenticationSession(
        clientSecret: String,
        profileId: String,
        authenticationId: String,
        merchantId: String,
    ) {
        requireInternal(clientSecret.isNotBlank() && clientSecret != "null") { "clientSecret cannot be empty" }
        requireInternal(profileId.isNotBlank() && profileId != "null") { "profileId cannot be empty" }
        requireInternal(authenticationId.isNotBlank() && authenticationId != "null") { "authenticationId cannot be empty" }
        requireInternal(merchantId.isNotBlank() && merchantId != "null") { "merchantId cannot be empty" }
        this.clientSecret = clientSecret
        this.profileId = profileId
        this.authenticationId = authenticationId
        this.merchantId = merchantId
    }

    private fun requireInternal(value: Boolean, lazyMessage: () -> Any): Unit {
        if (!value) {
            val message = lazyMessage()
            throw ClickToPayException(message.toString(), ClickToPayErrorType.INVALID_PARAMETER)
        }
    }

    /**
     * Initializes a Click to Pay session using stored credentials.
     *
     * Uses credentials previously set via initAuthenticationSession.
     *
     * @param request3DSAuthentication Whether to request 3DS authentication
     * @return The initialized ClickToPaySession instance
     * @throws ClickToPayException if session initialization fails or credentials are not set
     */
    @Throws(ClickToPayException::class)
    override suspend fun initClickToPaySession(
        request3DSAuthentication: Boolean
    ): ClickToPaySession {
        requireInternal(!clientSecret.isNullOrBlank() && clientSecret != "null") { "clientSecret cannot be empty" }
        requireInternal(!profileId.isNullOrBlank() && profileId != "null") { "profileId cannot be empty" }
        requireInternal(!authenticationId.isNullOrBlank() && authenticationId != "null") { "authenticationId cannot be empty" }
        requireInternal(!merchantId.isNullOrBlank() && merchantId != "null") { "merchantId cannot be empty" }

        return initClickToPaySession(
            clientSecret!!,
            profileId!!,
            authenticationId!!,
            merchantId!!,
            request3DSAuthentication
        )
    }

    /**
     * Initializes a Click to Pay session with explicit credentials.
     *
     * Allows initializing a session without calling initAuthenticationSession first.
     *
     * @param clientSecret The client secret from the payment intent
     * @param profileId The merchant profile identifier
     * @param authenticationId The authentication session identifier
     * @param merchantId The merchant identifier
     * @param request3DSAuthentication Whether to request 3DS authentication
     * @return The initialized ClickToPaySession instance
     * @throws ClickToPayException if session initialization fails
     */
    @Throws(ClickToPayException::class)
    override suspend fun initClickToPaySession(
        clientSecret: String,
        profileId: String,
        authenticationId: String,
        merchantId: String,
        request3DSAuthentication: Boolean
    ): ClickToPaySession {
        if (activeClickToPay != null && activeClickToPay !== clickToPaySession) {
            try {
                activeClickToPay?.closeInternal()
            }catch(_ : Exception){
            }
        }
        clickToPaySession.initClickToPaySession(
            clientSecret,
            profileId,
            authenticationId,
            merchantId,
            request3DSAuthentication
        )
        activeClickToPay = clickToPaySession
        return clickToPaySession
    }

    /**
     * Get the existing Active ClickToPay Session
     *
     */
    @Throws(Exception::class)
    override suspend fun getActiveClickToPaySession(
        activity: Activity
    ): ClickToPaySession {
        val session = activeClickToPay
        if (session != null){
            requireInternal(!clientSecret.isNullOrBlank() && clientSecret != "null") { "clientSecret cannot be empty" }
            requireInternal(!profileId.isNullOrBlank() && profileId != "null") { "profileId cannot be empty" }
            requireInternal(!authenticationId.isNullOrBlank() && authenticationId != "null") { "authenticationId cannot be empty" }
            requireInternal(!merchantId.isNullOrBlank() && merchantId != "null") { "merchantId cannot be empty" }
            return session.getActiveClickToPaySession(
                clientSecret!!,
                profileId!!,
                authenticationId!!,
                merchantId!!,
                activity
            )
        }else{
            throw ClickToPayException(
                "No session found for the ClickToPay",
                ClickToPayErrorType.SESSION_NOT_FOUND
            )
        }
    }

    /**
     * Initializes a 3DS authentication session.
     *
     * Currently a no-op placeholder for future 3DS functionality.
     */
    @Throws(Exception::class)
    override suspend fun initThreeDSSession() {}
    companion object {
        @Volatile
        private var activeClickToPay: ClickToPaySession? = null
    }
}

package io.hyperswitch.webview.utils

class DynamicImpl(
    private val value: Any?,
) : Dynamic {
    override val type: ReadableType
        get() =
            when (value) {
                null -> ReadableType.Null
                is Boolean -> ReadableType.Boolean
                is Number -> ReadableType.Number
                is String -> ReadableType.String
                is ReadableMap -> ReadableType.Map
                is ReadableArray -> ReadableType.Array
                else -> ReadableType.Null
            }

    override val isNull: Boolean
        get() = value == null

    override fun asArray(): ReadableArray? = value as? ReadableArray

    override fun asBoolean(): Boolean = value as? Boolean ?: false

    override fun asDouble(): Double =
        when (value) {
            is Double -> value
            is Int -> value.toDouble()
            is Long -> value.toDouble()
            is Float -> value.toDouble()
            else -> 0.0
        }

    override fun asInt(): Int =
        when (value) {
            is Int -> value
            is Double -> value.toInt()
            is Long -> value.toInt()
            is Float -> value.toInt()
            else -> 0
        }

    override fun asMap(): ReadableMap? = value as? ReadableMap

    override fun asString(): String? = value as? String

    override fun recycle() {
        // No-op for now, can be used for object pooling if needed
    }
}

package io.hyperswitch

/**
 * Typed payload hierarchy for payment events.
 *
 * Each subclass mirrors the corresponding RN-side typed record in PaymentEvents.res exactly.
 * This 1:1 contract means merchants receive structured, type-safe data instead of raw maps.
 */
sealed class PaymentEventData() {

    /**
     * Card information event payload.
     * Matches the canonical cardDetailsChange structure exactly.
     *
     * @property bin                  First 6 digits of the card number, or null if fewer than 6 entered
     * @property extendedBin          First 8 digits of the card number, or null if fewer than 8 entered
     * @property last4                Last 4 digits of the card number, or null if fewer than 4 entered
     * @property brand                Card network brand (e.g. "Visa", "Mastercard"), or null if unknown
     * @property expiryMonth          Two-digit expiry month (e.g. "01"), or null if not entered
     * @property expiryYear           Four-digit expiry year (e.g. "2025"), or null if not entered
     * @property formattedExpiry      Formatted expiry string (e.g. "01/25"), or null if not complete
     * @property isCardNumberComplete Whether the card number passes length validation
     * @property isCvcComplete        Whether the CVC passes length validation for the given brand
     * @property isExpiryComplete     Whether the expiry is valid and not in the past
     * @property isCardNumberValid    Whether the card number passes Luhn validation
     * @property isExpiryValid        Whether the expiry date is valid
     */
    data class CardInfo(
        val bin: String?,
        val extendedBin: String?,
        val last4: String?,
        val brand: String?,
        val expiryMonth: String?,
        val expiryYear: String?,
        val formattedExpiry: String?,
        val isCardNumberComplete: Boolean,
        val isCvcComplete: Boolean,
        val isExpiryComplete: Boolean,
        val isCardNumberValid: Boolean,
        val isExpiryValid: Boolean,
    ) : PaymentEventData() {

        companion object {
            fun fromMap(map: Map<String, Any>): CardInfo = CardInfo(
                bin = map["bin"] as? String,
                extendedBin = map["extendedBin"] as? String,
                last4 = map["last4"] as? String,
                brand = map["brand"] as? String,
                expiryMonth = map["expiryMonth"] as? String,
                expiryYear = map["expiryYear"] as? String,
                formattedExpiry = map["formattedExpiry"] as? String,
                isCardNumberComplete = (map["isCardNumberComplete"] as? Boolean) ?: false,
                isCvcComplete = (map["isCvcComplete"] as? Boolean) ?: false,
                isExpiryComplete = (map["isExpiryComplete"] as? Boolean) ?: false,
                isCardNumberValid = (map["isCardNumberValid"] as? Boolean) ?: false,
                isExpiryValid = (map["isExpiryValid"] as? Boolean) ?: false,
            )
        }
    }

    /**
     * Payment method status event payload.
     * Matches the canonical paymentMethodChange structure exactly.
     *
     * @property paymentMethod        Payment method category (e.g., "card", "wallet", "bank_redirect")
     * @property paymentMethodType    Payment method sub-type (e.g., "sofort", "ideal")
     * @property isSavedPaymentMethod Whether a saved payment method was selected
     * @property isOneClickWallet     Whether a one-click wallet was selected
     */
    data class PaymentMethodStatus(
        val paymentMethod: String,
        val paymentMethodType: String,
        val isSavedPaymentMethod: Boolean,
        val isOneClickWallet: Boolean,
    ) : PaymentEventData() {

        companion object {
            fun fromMap(map: Map<String, Any>): PaymentMethodStatus = PaymentMethodStatus(
                paymentMethod = (map["paymentMethod"] as? String).orEmpty(),
                paymentMethodType = (map["paymentMethodType"] as? String).orEmpty(),
                isSavedPaymentMethod = (map["isSavedPaymentMethod"] as? Boolean) ?: false,
                isOneClickWallet = (map["isOneClickWallet"] as? Boolean) ?: false,
            )
        }
    }

    /**
     * Form status values for type-safe status handling.
     */
    enum class FormStatusValue {
        EMPTY,
        FILLING,
        COMPLETE;

        companion object {
            fun fromString(value: String): FormStatusValue? =
                FormStatusValue.entries.find { it.name == value }
        }
    }

    /**
     * Form status event payload.
     *
     * @property status Form status, or null for unknown values
     */
    data class FormStatus(
        val status: FormStatusValue?,
    ) : PaymentEventData() {

        companion object {
            fun fromMap(map: Map<String, Any>): FormStatus = FormStatus(
                status = (map["status"] as? String)?.let { FormStatusValue.fromString(it) }
            )
        }
    }

    /**
     * Address information event payload.
     * Matches the canonical billingDetailsChange structure exactly.
     *
     * @property country    Country code
     * @property state      State/province
     * @property postalCode Postal/ZIP code
     */
    data class PaymentMethodInfoAddress(
        val country: String,
        val state: String,
        val postalCode: String,
    ) : PaymentEventData() {

        companion object {
            fun fromMap(map: Map<String, Any>): PaymentMethodInfoAddress = PaymentMethodInfoAddress(
                country = (map["country"] as? String).orEmpty(),
                state = (map["state"] as? String).orEmpty(),
                postalCode = (map["postalCode"] as? String).orEmpty(),
            )
        }
    }

    /**
     * CVC status event payload.
     *
     * @property isCvcFocused   Whether the CVC field is currently focused
     * @property isCvcBlur      Whether the CVC field has lost focus
     * @property isCvcEmpty     Whether the CVC field is empty
     * @property isCvcComplete  Whether the CVC passes length validation for the given brand
     */
    data class CvcStatus(
        val isCvcFocused: Boolean,
        val isCvcBlur: Boolean,
        val isCvcEmpty: Boolean,
        val isCvcComplete: Boolean,
    ) : PaymentEventData() {

        companion object {
            @Suppress("UNCHECKED_CAST")
            fun fromMap(map: Map<String, Any>): CvcStatus {
                val nested = map["cvcStatus"] as? Map<String, Any> ?: map
                return CvcStatus(
                    isCvcFocused = (nested["isCvcFocused"] as? Boolean) ?: false,
                    isCvcBlur = (nested["isCvcBlur"] as? Boolean) ?: false,
                    isCvcEmpty = (nested["isCvcEmpty"] as? Boolean) ?: true,
                    isCvcComplete = (nested["isCvcComplete"] as? Boolean) ?: false,
                )
            }
        }
    }

    companion object {
        /**
         * Parse a [PaymentEventData] subclass from a raw event-type string and payload map.
         * Returns null for unrecognised event types (forward-compatibility).
         *
         * This is called automatically when constructing a [PaymentEvent] — consumers never
         * need to call this directly.
         */
        fun fromEventType(eventType: String, payload: Map<String, Any>): PaymentEventData? =
            when (eventType) {
                "cardDetailsChange" -> CardInfo.fromMap(payload)
                "paymentMethodChange" -> PaymentMethodStatus.fromMap(payload)
                "formStatusChange" -> FormStatus.fromMap(payload)
                "billingDetailsChange" -> PaymentMethodInfoAddress.fromMap(payload)
                "cvcStatusChange" -> CvcStatus.fromMap(payload)
                else -> null
            }
    }
}

package io.hyperswitch

interface PaymentEventListener {
    fun onPaymentEvent(event: PaymentEvent)
}

data class PaymentEvent(
    val type: String,
    val payload: Map<String, Any>,
) {
    val data: PaymentEventData? by lazy { PaymentEventData.fromEventType(type, payload) }
}

package io.hyperswitch

import android.app.Activity
import io.hyperswitch.lite.DefaultPaymentSessionLauncherLite
import io.hyperswitch.model.HyperswitchBaseConfiguration
import io.hyperswitch.model.PaymentSessionConfiguration
import io.hyperswitch.paymentsession.PaymentSessionHandler
import io.hyperswitch.paymentsession.PaymentSessionLauncher
import io.hyperswitch.paymentsheet.PaymentSheet
import io.hyperswitch.paymentsheet.PaymentResult

/**
 * A class that manages payment sessions using a [io.hyperswitch.paymentsession.PaymentSessionLauncher].
 *
 * This class provides methods for initializing a payment session, presenting a payment sheet,
 * and retrieving customer saved payment methods.
 */
class PaymentSession internal constructor(private val paymentSessionLauncher: PaymentSessionLauncher) {

    constructor(activity: Activity, config: HyperswitchBaseConfiguration?, sessionConfig: PaymentSessionConfiguration) : this(
        DefaultPaymentSessionLauncherLite(activity, config)
    ) {
        initPaymentSession(sessionConfig)
    }

    /**
     * Initializes the payment session with the given PaymentSessionConfiguration.
     *
     * @param sessionConfig The session configuration including the client secret.
     */
    fun initPaymentSession(sessionConfig: PaymentSessionConfiguration) {
        paymentSessionLauncher.initPaymentSession(sessionConfig)
    }

    /**
     * Presents the payment sheet to the user.
     *
     * @param resultCallback A callback that will be invoked when the payment sheet is closed.
     */
    fun presentPaymentSheet(resultCallback: (PaymentResult) -> Unit) {
        paymentSessionLauncher.presentPaymentSheet(configuration = null, subscribe = null, resultCallback)
    }

    /**
     * Presents the payment sheet to the user.
     *
     * @param configuration The configuration for the payment sheet.
     * @param resultCallback A callback that will be invoked when the payment sheet is closed.
     */
    fun presentPaymentSheet(
        configuration: PaymentSheet.Configuration, resultCallback: (PaymentResult) -> Unit
    ) {
        paymentSessionLauncher.presentPaymentSheet(configuration, subscribe = null, resultCallback)
    }

    /**
     * Presents the payment sheet to the user with a configuration map.
     *
     * @param configurationMap The configuration map for the payment sheet.
     * @param resultCallback A callback that will be invoked when the payment sheet is closed.
     */
    fun presentPaymentSheet(
        configurationMap: Map<String, Any?>,
        resultCallback: (PaymentResult) -> Unit
    ) {
        paymentSessionLauncher.presentPaymentSheet(configurationMap, subscribe = null, resultCallback)
    }

    /**
     * Retrieves the customer's saved payment methods.
     *
     * @param savedPaymentMethodCallback A callback that will be invoked with the customer's saved payment methods.
     */
    fun getCustomerSavedPaymentMethods(savedPaymentMethodCallback: ((PaymentSessionHandler) -> Unit)) {
        paymentSessionLauncher.getCustomerSavedPaymentMethods(savedPaymentMethodCallback)
    }
}

package io.hyperswitch

import android.content.Context
import android.content.SharedPreferences
import android.os.Parcelable
import androidx.annotation.RestrictTo
import kotlinx.parcelize.Parcelize
import androidx.core.content.edit

@Parcelize
data class PaymentConfiguration
@RestrictTo(RestrictTo.Scope.LIBRARY_GROUP) constructor(
    val publishableKey: String? = null,
    val profileId: String? = null,
) : Parcelable {

    /**
     * Manages saving and loading [PaymentConfiguration] data to SharedPreferences.
     */
    private class Store(context: Context) {
        private val prefs: SharedPreferences =
            context.applicationContext.getSharedPreferences(NAME, 0)

        @JvmSynthetic
        fun save(
            publishableKey: String?,
            profileId: String?,
        ) {
            prefs.edit {
                putString(KEY_PUBLISHABLE_KEY, publishableKey)
                    .putString(KEY_ACCOUNT_ID, profileId)
            }
        }

        @JvmSynthetic
        internal fun load(): PaymentConfiguration? {
            return prefs.getString(KEY_PUBLISHABLE_KEY, null)?.let { publishableKey ->
                PaymentConfiguration(
                    publishableKey = publishableKey,
                    profileId = prefs.getString(KEY_ACCOUNT_ID, null),
                )
            }
        }

        private companion object {
            private val NAME = PaymentConfiguration::class.java.canonicalName

            private const val KEY_PUBLISHABLE_KEY = "key_publishable_key"
            private const val KEY_ACCOUNT_ID = "key_account_id"
        }
    }

    companion object {
        private var instance: PaymentConfiguration? = null

        /**
         * Attempts to load a [PaymentConfiguration] instance. First attempt to use the class's
         * singleton instance. If unavailable, attempt to load from [Store].
         *
         * @param context application context
         * @return a [PaymentConfiguration] instance, or throw an exception
         */
        @JvmStatic
        fun getInstance(context: Context): PaymentConfiguration {
            return instance ?: loadInstance(context)
        }

        private fun loadInstance(context: Context): PaymentConfiguration {
            return Store(context).load()?.let {
                instance = it
                it
            } ?: throw IllegalStateException(
                "PaymentConfiguration was not initialized. Call PaymentConfiguration.init()."
            )
        }
        /**
         * A publishable key from the Dashboard's [API keys](https://app.hyperswitch.io/apikeys) page.
         */
        @JvmStatic
        @JvmOverloads
        fun init(
            context: Context,
            publishableKey: String? = null,
            profileId: String? = null,
        ) {
            instance = PaymentConfiguration(
                publishableKey = publishableKey,
                profileId = profileId,
            )
            Store(context).save(
                publishableKey = publishableKey,
                profileId = profileId,
            )
        }

        @RestrictTo(RestrictTo.Scope.LIBRARY_GROUP)
        @JvmSynthetic
        fun clearInstance() {
            instance = null
        }

        fun preload() {}
    }
}

package io.hyperswitch


class PaymentEventSubscriptionBuilder {
    private val handlers = mutableMapOf<EventType, (PaymentEvent) -> Unit>()

    fun on(eventType: EventType, handler: (PaymentEvent) -> Unit) {
        handlers[eventType] = handler
    }

    fun build(): Pair<PaymentEventSubscription, PaymentEventListener> {
        val subscribedEvents = handlers.keys.toList()

        val subscription = PaymentEventSubscription(
            eventTypes = subscribedEvents
        )

        // Build an O(1) lookup map keyed by event type string
        val dispatchMap: Map<String, (PaymentEvent) -> Unit> =
            handlers.entries.associate { (k, v) -> k.value to v }

        // Create dispatcher that routes events to appropriate handlers
        val listener = object : PaymentEventListener {
            override fun onPaymentEvent(event: PaymentEvent) {
                dispatchMap[event.type]?.invoke(event)
            }
        }

        return Pair(subscription, listener)
    }

    private fun findMatchingHandler(eventTypeString: String): ((PaymentEvent) -> Unit)? {
        return handlers.entries.find { it.key.value == eventTypeString }?.value
    }
}

/**
 * PaymentEventSubscription holds the list of subscribed event types.
 */
data class PaymentEventSubscription(
    val eventTypes: List<EventType>
) {
    /**
     * Checks if a specific event type string is subscribed.
     */
    fun isSubscribed(eventTypeString: String): Boolean {
        return eventTypes.any { it.value == eventTypeString }
    }

    fun getSubscribedEventStrings(): List<String> {
        return eventTypes.map { it.value }
    }
}

